/* Juniper EX configuration for crb-spine1 */
/* Hardware: EX4400-24T (member 0) */
/* Made by Multi-Vendor Switch Config Builder 0.2.0. Review before you commit. */
system {
    host-name crb-spine1;
    domain-name crb.lab.local;
    name-server {
        10.99.0.53;
        1.1.1.1;
    }
    domain-search crb.lab.local;
    ntp {
        server 10.99.0.123 prefer;
        server time.cloudflare.com;
    }
    login {
        message "EVPN-VXLAN CRB data center fabric lab. Gateways live on the spines. Lab use only.";
        user labadmin {
            class super-user;
            authentication {
                encrypted-password "$6$UVR2Iqx4d5UDYzYU$.Wo5CPsfQwYn6rdZws5ASWUz5EGVA5e4Mv3FqI83g90smxAQE926mzzL.OAK9mPz6YbzERL35K.E.h3FugDp40";
            }
        }
        retry-options {
            tries-before-disconnect 3;
            backoff-threshold 2;
            lockout-period 5;
        }
    }
    management-instance;
    root-authentication {
        encrypted-password "$6$UVR2Iqx4d5UDYzYU$.Wo5CPsfQwYn6rdZws5ASWUz5EGVA5e4Mv3FqI83g90smxAQE926mzzL.OAK9mPz6YbzERL35K.E.h3FugDp40";
    }
    services {
        ssh {
            root-login deny;
            protocol-version v2;
            connection-limit 10;
            rate-limit 5;
        }
        netconf {
            ssh {
                port 830;
            }
        }
    }
    syslog {
        file messages {
            any notice;
            authorization info;
        }
        file interactive-commands {
            interactive-commands any;
        }
    }
}
interfaces {
    em0 {
        unit 0 {
            family inet {
                address 10.99.2.11/24;
            }
        }
    }
    irb {
        unit 100 {
            family inet {
                address 10.100.0.254/24 {
                    virtual-gateway-address 10.100.0.1;
                }
            }
        }
        unit 110 {
            family inet {
                address 10.101.0.254/24 {
                    virtual-gateway-address 10.101.0.1;
                }
            }
        }
        unit 120 {
            family inet {
                address 10.102.0.254/24 {
                    virtual-gateway-address 10.102.0.1;
                }
            }
        }
        unit 130 {
            family inet {
                address 10.103.0.254/24 {
                    virtual-gateway-address 10.103.0.1;
                }
            }
        }
        unit 200 {
            family inet {
                address 10.200.0.254/24 {
                    virtual-gateway-address 10.200.0.1;
                }
            }
        }
        unit 210 {
            family inet {
                address 10.201.0.254/24 {
                    virtual-gateway-address 10.201.0.1;
                }
            }
        }
        unit 300 {
            family inet {
                address 172.16.30.254/24 {
                    virtual-gateway-address 172.16.30.1;
                }
            }
        }
    }
    xe-0/2/0 {
        description "Fabric link to crb-leaf1 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.2.0/31;
            }
        }
    }
    xe-0/2/1 {
        description "Fabric link to crb-leaf2 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.2.4/31;
            }
        }
    }
    xe-0/2/2 {
        description "Fabric link to crb-leaf3 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.2.8/31;
            }
        }
    }
    xe-0/2/3 {
        description "Fabric link to crb-leaf4 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.2.12/31;
            }
        }
    }
    lo0 {
        unit 0 {
            family inet {
                address 10.255.2.1/32;
            }
        }
        unit 11 {
            family inet;
        }
        unit 12 {
            family inet;
        }
        unit 13 {
            family inet;
        }
    }
}
routing-instances {
    mgmt_junos {
        routing-options {
            static {
                route 0.0.0.0/0 next-hop 10.99.2.1;
            }
        }
    }
    PROD {
        instance-type vrf;
        interface lo0.11;
        interface irb.100;
        interface irb.110;
        interface irb.120;
        interface irb.130;
        route-distinguisher 10.255.2.1:11;
        vrf-target target:65200:19001;
        protocols {
            evpn {
                ip-prefix-routes {
                    advertise direct-nexthop;
                    encapsulation vxlan;
                    vni 19001;
                }
            }
        }
    }
    DEV {
        instance-type vrf;
        interface lo0.12;
        interface irb.200;
        interface irb.210;
        route-distinguisher 10.255.2.1:12;
        vrf-target target:65200:19002;
        protocols {
            evpn {
                ip-prefix-routes {
                    advertise direct-nexthop;
                    encapsulation vxlan;
                    vni 19002;
                }
            }
        }
    }
    DMZ {
        instance-type vrf;
        interface lo0.13;
        interface irb.300;
        route-distinguisher 10.255.2.1:13;
        vrf-target target:65200:19003;
        protocols {
            evpn {
                ip-prefix-routes {
                    advertise direct-nexthop;
                    encapsulation vxlan;
                    vni 19003;
                }
            }
        }
    }
}
snmp {
    location "EVE-NG lab";
    contact noc@lab.local;
}
vlans {
    PROD-WEB {
        description "VNI 20100";
        vlan-id 100;
        l3-interface irb.100;
        vxlan {
            vni 20100;
        }
    }
    PROD-APP {
        description "VNI 20110";
        vlan-id 110;
        l3-interface irb.110;
        vxlan {
            vni 20110;
        }
    }
    PROD-DB {
        description "VNI 20120";
        vlan-id 120;
        l3-interface irb.120;
        vxlan {
            vni 20120;
        }
    }
    BACKUP {
        description "VNI 20130";
        vlan-id 130;
        l3-interface irb.130;
        vxlan {
            vni 20130;
        }
    }
    DEV-WEB {
        description "VNI 20200";
        vlan-id 200;
        l3-interface irb.200;
        vxlan {
            vni 20200;
        }
    }
    DEV-APP {
        description "VNI 20210";
        vlan-id 210;
        l3-interface irb.210;
        vxlan {
            vni 20210;
        }
    }
    DMZ-PUBLIC {
        description "VNI 20300";
        vlan-id 300;
        l3-interface irb.300;
        vxlan {
            vni 20300;
        }
    }
    VMOTION {
        description "VNI 20900";
        vlan-id 900;
        vxlan {
            vni 20900;
        }
    }
}
routing-options {
    router-id 10.255.2.1;
    autonomous-system 65200;
    forwarding-table {
        export ECMP-LOAD-BALANCE;
    }
}
policy-options {
    policy-statement ECMP-LOAD-BALANCE {
        then {
            load-balance per-packet;
        }
    }
}
protocols {
    ospf {
        reference-bandwidth 100g;
        area 0.0.0.0 {
            interface xe-0/2/0.0 {
                interface-type p2p;
            }
            interface xe-0/2/1.0 {
                interface-type p2p;
            }
            interface xe-0/2/2.0 {
                interface-type p2p;
            }
            interface xe-0/2/3.0 {
                interface-type p2p;
            }
            interface lo0.0 {
                passive;
            }
        }
    }
    bgp {
        group EVPN-OVERLAY {
            type internal;
            description "EVPN overlay";
            local-address 10.255.2.1;
            family evpn {
                signaling;
            }
            multipath;
            cluster 10.255.2.1;
            neighbor 10.255.2.3;
            neighbor 10.255.2.4;
            neighbor 10.255.2.5;
            neighbor 10.255.2.6;
            neighbor 10.255.2.2;
        }
    }
    evpn {
        encapsulation vxlan;
        extended-vni-list all;
        default-gateway {
            no-gateway-community;
        }
    }
    lldp {
        interface all;
    }
    lldp-med {
        interface all;
    }
    rstp {
        interface all;
        bpdu-block-on-edge;
    }
}
switch-options {
    vtep-source-interface lo0.0;
    route-distinguisher 10.255.2.1:1;
    vrf-target target:65200:1;
}
forwarding-options {
    storm-control-profiles storm-default {
        all {
            bandwidth-percentage 5;
        }
    }
}

